
import keyword
import math
import re

from dataclasses import dataclass, field


# ==========================================================
# GENERATED PROGRAM DATA
# ==========================================================

@dataclass
class GeneratedSection:
    """Represents Python code generated by one flowchart node."""

    node_index: int
    node_id: object
    node_type: str
    node_name: str

    code: str
    explanation: str
    concepts: list = field(default_factory=list)

    start_line: int = 0
    end_line: int = 0

    node_ref: object = field(
        default=None,
        repr=False,
        compare=False
    )


@dataclass
class GeneratedProgram:
    """Contains the complete generated program and its learning data."""

    code: str
    sections: list

    def get_section_by_index(self, index):
        for section in self.sections:
            if section.node_index == index:
                return section

        return None

    def get_section_for_node(self, node):
        for section in self.sections:
            if section.node_ref is node:
                return section

        node_id = getattr(node, "node_id", None)

        for section in self.sections:
            if section.node_id == node_id:
                return section

        return None

    def get_all_concepts(self):
        concepts = []

        for section in self.sections:
            for concept in section.concepts:
                if concept not in concepts:
                    concepts.append(concept)

        return concepts


class CodeGenerationError(Exception):
    """Raised when a flowchart cannot be converted into Python."""
    pass


# ==========================================================
# PYTHON CODE GENERATOR
# ==========================================================

class CodeGenerator:

    SUPPORTED_TYPES = {
        "START",
        "INPUT",
        "OPERATION",
        "CONDITION",
        "OUTPUT",
        "END",
    }

    COMPARISONS = {
        "Equal to": "==",
        "Equals": "==",
        "Equal": "==",
        "==": "==",

        "Not equal to": "!=",
        "Not equal": "!=",
        "!=": "!=",

        "Greater than": ">",
        ">": ">",

        "Less than": "<",
        "<": "<",

        "Greater than or equal to": ">=",
        ">=": ">=",

        "Less than or equal to": "<=",
        "<=": "<=",
    }

    ARITHMETIC_OPERATIONS = {
        "Add": {
            "operator": "+",
            "name": "addition",
            "concept": "Addition (+)",
        },
        "Subtract": {
            "operator": "-",
            "name": "subtraction",
            "concept": "Subtraction (-)",
        },
        "Multiply": {
            "operator": "*",
            "name": "multiplication",
            "concept": "Multiplication (*)",
        },
        "Divide": {
            "operator": "/",
            "name": "division",
            "concept": "Division (/)",
        },
    }

    def __init__(self, nodes, connections):

        self.nodes = list(nodes)
        self.connections = list(connections)

        self.node_indexes = {}
        self.outgoing = {}

        self.sections = []
        self.visited = set()

        self.lines = []

        self.numeric_variables = set()

    # ======================================================
    # NODE INFORMATION
    # ======================================================

    def get_node_type(self, node):

        value = getattr(node, "node_type", "")
        value = getattr(value, "value", value)

        return str(value).split(".")[-1].upper()

    def get_node_name(self, node):

        return str(
            getattr(
                node,
                "node_name",
                self.get_node_type(node)
            )
        )

    def get_setting(self, node, key, default=""):

        settings = getattr(node, "settings", {}) or {}

        return settings.get(key, default)

    def get_connections(self, node):

        return self.outgoing.get(id(node), [])

    # ======================================================
    # VARIABLE VALIDATION
    # ======================================================

    def validate_variable(self, value):

        name = str(value).strip()

        if name.startswith("{") and name.endswith("}"):
            name = name[1:-1].strip()

        if not name:
            raise CodeGenerationError(
                "Variable name cannot be empty."
            )

        if not name.isidentifier() or keyword.iskeyword(name):
            raise CodeGenerationError(
                f"'{name}' is not a valid Python variable name."
            )

        return name

    # ======================================================
    # VARIABLE REFERENCE DETECTION
    # ======================================================

    def get_variable_reference(self, expression):

        if not isinstance(expression, str):
            return None

        expression = expression.strip()

        match = re.fullmatch(
            r"\{([^{}]+)\}",
            expression
        )

        if match:
            return self.validate_variable(match.group(1))

        if "{" in expression or "}" in expression:
            raise CodeGenerationError(
                f"Invalid variable reference: {expression!r}. "
                "Use {variable_name}."
            )

        return None

    # ======================================================
    # CONVERT VALUES INTO PYTHON EXPRESSIONS
    # ======================================================

    def to_python_expression(self, value):

        if not isinstance(value, str):
            return repr(value)

        value = value.strip()

        if not value:
            return "''"

        exact_reference = re.fullmatch(
            r"\{([A-Za-z_]\w*)\}",
            value
        )

        if exact_reference:

            variable = self.validate_variable(
                exact_reference.group(1)
            )

            return variable

        try:
            number = float(value)

            if not math.isfinite(number):
                raise ValueError

            if number.is_integer():
                return str(int(number))

            return repr(number)

        except ValueError:
            pass

        placeholders = re.findall(
            r"\{([^{}]+)\}",
            value
        )

        if placeholders:

            for placeholder in placeholders:
                self.validate_variable(placeholder)

            cleaned = re.sub(
                r"\{[^{}]+\}",
                "",
                value
            )

            if "{" in cleaned or "}" in cleaned:
                raise CodeGenerationError(
                    f"Invalid variable placeholder in {value!r}."
                )

            return "f" + repr(value)

        if "{" in value or "}" in value:
            raise CodeGenerationError(
                f"Invalid variable placeholder in {value!r}."
            )

        return repr(value)

    # ======================================================
    # CONVERT MATHEMATICAL OPERANDS
    # ======================================================

    def to_python_operand(self, expression):

        if expression is None:
            raise CodeGenerationError(
                "A mathematical operand cannot be empty."
            )

        expression = str(expression).strip()

        if not expression:
            raise CodeGenerationError(
                "A mathematical operand cannot be empty."
            )

        # Variable reference: {num1} -> num1
        variable = self.get_variable_reference(expression)

        if variable is not None:
            return variable

        # Direct numeric value: 10 -> 10
        try:
            number = float(expression)

            if not math.isfinite(number):
                raise ValueError

            if number.is_integer():
                return str(int(number))

            return repr(number)

        except ValueError:
            raise CodeGenerationError(
                f"Invalid mathematical operand: {expression!r}. "
                "Use a number such as 10 or a variable reference "
                "such as {num1}."
            )

    # ======================================================
    # DETECT NUMERIC VARIABLES
    # ======================================================

    def detect_numeric_variables(self):

        numeric = set()

        for node in self.nodes:

            node_type = self.get_node_type(node)
            settings = getattr(node, "settings", {}) or {}

            if node_type == "OPERATION":

                # NEW MATHEMATICAL OPERATION FORMAT
                if "operation" in settings:

                    first = self.get_setting(
                        node,
                        "first_variable",
                        ""
                    )

                    second = self.get_setting(
                        node,
                        "second_variable",
                        ""
                    )

                    result = self.get_setting(
                        node,
                        "result_variable",
                        ""
                    )

                    first_reference = self.get_variable_reference(
                        str(first)
                    )

                    second_reference = self.get_variable_reference(
                        str(second)
                    )

                    if first_reference:
                        numeric.add(first_reference)

                    if second_reference:
                        numeric.add(second_reference)

                    numeric.add(
                        self.validate_variable(result)
                    )

                else:
                    # LEGACY OPERATION FORMAT
                    action = self.get_setting(
                        node,
                        "action",
                        "Set a value"
                    )

                    variable = self.get_setting(
                        node,
                        "variable",
                        "value"
                    )

                    if action != "Set a value":

                        numeric.add(
                            self.validate_variable(variable)
                        )

                        amount = self.get_setting(
                            node,
                            "amount",
                            "1"
                        )

                        amount_reference = (
                            self.get_variable_reference(str(amount))
                        )

                        if amount_reference:
                            numeric.add(amount_reference)

            elif node_type == "CONDITION":

                variable = self.get_setting(
                    node,
                    "variable",
                    "value"
                )

                compare_value = self.get_setting(
                    node,
                    "compare_value",
                    "0"
                )

                try:
                    float(str(compare_value).strip())

                    numeric.add(
                        self.validate_variable(variable)
                    )

                except ValueError:
                    pass

        self.numeric_variables = numeric

    # ======================================================
    # GRAPH VALIDATION
    # ======================================================

    def validate_graph(self):

        if not self.nodes:
            raise CodeGenerationError(
                "Your flowchart is empty. Add some nodes first."
            )

        starts = []

        valid_nodes = {
            id(node) for node in self.nodes
        }

        self.node_indexes = {
            id(node): index
            for index, node in enumerate(self.nodes)
        }

        self.outgoing = {
            id(node): []
            for node in self.nodes
        }

        for node in self.nodes:

            node_type = self.get_node_type(node)

            if node_type not in self.SUPPORTED_TYPES:
                raise CodeGenerationError(
                    f"Unsupported node type: {node_type}"
                )

            if node_type == "START":
                starts.append(node)

        if len(starts) != 1:
            raise CodeGenerationError(
                "Your flowchart must have exactly one START node. "
                f"Found: {len(starts)}."
            )

        for connection in self.connections:

            source = getattr(
                connection,
                "source_node",
                None
            )

            target = getattr(
                connection,
                "target_node",
                None
            )

            if id(source) not in valid_nodes:
                raise CodeGenerationError(
                    "A connection has an invalid source node."
                )

            if id(target) not in valid_nodes:
                raise CodeGenerationError(
                    "A connection has an invalid target node."
                )

            if source is target:
                raise CodeGenerationError(
                    "A node cannot connect directly to itself."
                )

            branch = getattr(
                connection,
                "source_port_type",
                getattr(connection, "branch", "output")
            )

            branch = str(branch).strip().lower()

            self.outgoing[id(source)].append(
                (branch, target)
            )

        for node in self.nodes:

            node_type = self.get_node_type(node)
            connections = self.get_connections(node)

            if node_type == "END":

                if connections:
                    raise CodeGenerationError(
                        f"END node '{self.get_node_name(node)}' "
                        "cannot have outgoing connections."
                    )

            elif node_type == "CONDITION":

                true_count = sum(
                    1 for branch, target in connections
                    if branch == "true"
                )

                false_count = sum(
                    1 for branch, target in connections
                    if branch == "false"
                )

                if true_count != 1:
                    raise CodeGenerationError(
                        f"Condition '{self.get_node_name(node)}' "
                        "needs exactly one TRUE connection."
                    )

                if false_count != 1:
                    raise CodeGenerationError(
                        f"Condition '{self.get_node_name(node)}' "
                        "needs exactly one FALSE connection."
                    )

                if len(connections) != 2:
                    raise CodeGenerationError(
                        f"Condition '{self.get_node_name(node)}' "
                        "has an unexpected outgoing connection."
                    )

            else:

                if len(connections) != 1:
                    raise CodeGenerationError(
                        f"Node '{self.get_node_name(node)}' "
                        "needs exactly one outgoing connection. "
                        f"Found: {len(connections)}."
                    )

        self.validate_no_cycles(starts[0])
        self.validate_reachability(starts[0])

        return starts[0]

    # ======================================================
    # CYCLE VALIDATION
    # ======================================================

    def validate_no_cycles(self, start):

        active = set()
        completed = set()

        def visit(node):

            node_key = id(node)

            if node_key in active:
                raise CodeGenerationError(
                    "A loop or circular connection was detected. "
                    "Loop generation will be added in a later stage."
                )

            if node_key in completed:
                return

            active.add(node_key)

            for branch, target in self.get_connections(node):
                visit(target)

            active.remove(node_key)
            completed.add(node_key)

        visit(start)

    # ======================================================
    # REACHABILITY VALIDATION
    # ======================================================

    def validate_reachability(self, start):

        reachable = set()

        def visit(node):

            node_key = id(node)

            if node_key in reachable:
                return

            reachable.add(node_key)

            for branch, target in self.get_connections(node):
                visit(target)

        visit(start)

        unreachable = [
            node for node in self.nodes
            if id(node) not in reachable
        ]

        if unreachable:

            names = ", ".join(
                self.get_node_name(node)
                for node in unreachable
            )

            raise CodeGenerationError(
                "Some nodes cannot be reached from START: "
                + names
            )

    # ======================================================
    # FIND WHERE IF/ELSE BRANCHES REJOIN
    # ======================================================

    def get_reachable_distances(self, start):

        distances = {
            id(start): 0
        }

        queue = [start]

        while queue:

            current = queue.pop(0)
            current_distance = distances[id(current)]

            for branch, target in self.get_connections(current):

                target_key = id(target)

                if target_key not in distances:

                    distances[target_key] = current_distance + 1
                    queue.append(target)

        return distances

    def find_branch_merge(self, true_target, false_target):

        true_distances = self.get_reachable_distances(
            true_target
        )

        false_distances = self.get_reachable_distances(
            false_target
        )

        common = (
            set(true_distances)
            & set(false_distances)
        )

        if not common:
            raise CodeGenerationError(
                "The TRUE and FALSE branches do not rejoin. "
                "For this version, both branches must eventually "
                "reach a shared node."
            )

        merge_key = min(
            common,
            key=lambda key: (
                max(
                    true_distances[key],
                    false_distances[key]
                ),
                true_distances[key] + false_distances[key]
            )
        )

        for node in self.nodes:

            if id(node) == merge_key:
                return node

        raise CodeGenerationError(
            "Could not identify the branch merge node."
        )

    # ======================================================
    # ADD GENERATED SECTIONS
    # ======================================================

    def add_section(
        self,
        node,
        code_lines,
        explanation,
        concepts
    ):

        start_line = len(self.lines) + 1

        self.lines.extend(code_lines)

        end_line = len(self.lines)

        section = GeneratedSection(
            node_index=self.node_indexes[id(node)],
            node_id=getattr(node, "node_id", None),
            node_type=self.get_node_type(node),
            node_name=self.get_node_name(node),
            code="\n".join(code_lines),
            explanation=explanation,
            concepts=concepts,
            start_line=start_line,
            end_line=end_line,
            node_ref=node,
        )

        self.sections.append(section)

        return section

    # ======================================================
    # GENERATE ONE NODE
    # ======================================================

    def generate_node(self, node):

        node_type = self.get_node_type(node)
        node_name = self.get_node_name(node)

        if node_type == "START":

            return (
                [],
                "The START node marks where the flowchart begins. "
                "Python executes the generated instructions from "
                "top to bottom.",
                [
                    "Program execution",
                    "Program entry point",
                ]
            )

        elif node_type == "INPUT":

            variable = self.validate_variable(
                self.get_setting(node, "variable", "value")
            )

            question = self.get_setting(
                node,
                "question",
                "Enter a value:"
            )

            prompt = self.to_python_expression(question)

            if variable in self.numeric_variables:

                code = (
                    f"{variable} = float(input({prompt}))"
                )

                explanation = (
                    f"This node asks the user for information "
                    f"and stores it as a number in '{variable}'. "
                    "The float() function converts the input text "
                    "into a numeric value."
                )

                concepts = [
                    "Variables",
                    "input()",
                    "float()",
                    "Type conversion",
                    "Assignment operator (=)",
                ]

            else:

                code = (
                    f"{variable} = input({prompt})"
                )

                explanation = (
                    f"This node asks the user for information and "
                    f"stores the response in '{variable}'. "
                    "The input() function receives user input as text."
                )

                concepts = [
                    "Variables",
                    "input()",
                    "Assignment operator (=)",
                    "Strings",
                ]

            return (
                [code],
                explanation,
                concepts
            )

        elif node_type == "OPERATION":

            settings = getattr(node, "settings", {}) or {}

            # ==============================================
            # NEW MATHEMATICAL OPERATION FORMAT
            # ==============================================

            if "operation" in settings:

                first_expression = self.get_setting(
                    node,
                    "first_variable",
                    ""
                )

                second_expression = self.get_setting(
                    node,
                    "second_variable",
                    ""
                )

                result = self.validate_variable(
                    self.get_setting(
                        node,
                        "result_variable",
                        ""
                    )
                )

                first = self.to_python_operand(
                    first_expression
                )

                second = self.to_python_operand(
                    second_expression
                )

                operation_name = self.get_setting(
                    node,
                    "operation",
                    "Add"
                )

                operation = self.ARITHMETIC_OPERATIONS.get(
                    operation_name
                )

                if operation is None:
                    raise CodeGenerationError(
                        f"Unknown mathematical operation "
                        f"'{operation_name}' in node '{node_name}'."
                    )

                operator = operation["operator"]

                code = (
                    f"{result} = {first} {operator} {second}"
                )

                explanation = (
                    f"This node performs {operation['name']} "
                    f"using '{first}' and '{second}', then stores "
                    f"the result in '{result}'. "
                    f"The {operator} operator performs "
                    f"{operation['name']} in Python."
                )

                return (
                    [code],
                    explanation,
                    [
                        "Variables",
                        "Arithmetic",
                        operation["concept"],
                        "Assignment operator (=)",
                    ]
                )

            # ==============================================
            # LEGACY OPERATION FORMAT
            # ==============================================

            variable = self.validate_variable(
                self.get_setting(node, "variable", "value")
            )

            action = self.get_setting(
                node,
                "action",
                "Set a value"
            )

            if action == "Set a value":

                value = self.get_setting(
                    node,
                    "value",
                    "0"
                )

                expression = self.to_python_expression(value)

                return (
                    [f"{variable} = {expression}"],
                    f"This node creates or updates the variable "
                    f"'{variable}'. The assignment operator (=) "
                    "stores a value in a variable.",
                    [
                        "Variables",
                        "Assignment operator (=)",
                        "Data types",
                    ]
                )

            legacy_operations = {
                "Increase a value": {
                    "operator": "+=",
                    "name": "increases",
                    "concept": "Addition (+)",
                },
                "Decrease a value": {
                    "operator": "-=",
                    "name": "decreases",
                    "concept": "Subtraction (-)",
                },
                "Multiply a value": {
                    "operator": "*=",
                    "name": "multiplies",
                    "concept": "Multiplication (*)",
                },
                "Divide a value": {
                    "operator": "/=",
                    "name": "divides",
                    "concept": "Division (/)",
                },
            }

            if action in legacy_operations:

                operation = legacy_operations[action]

                amount = self.to_python_expression(
                    self.get_setting(node, "amount", "1")
                )

                return (
                    [
                        f"{variable} "
                        f"{operation['operator']} {amount}"
                    ],
                    f"This node {operation['name']} "
                    f"'{variable}' by the specified amount.",
                    [
                        "Variables",
                        "Arithmetic",
                        operation["concept"],
                        "Augmented assignment",
                    ]
                )

            raise CodeGenerationError(
                f"Unknown operation '{action}' "
                f"in node '{node_name}'."
            )

        elif node_type == "CONDITION":

            variable = self.validate_variable(
                self.get_setting(node, "variable", "value")
            )

            comparison = self.get_setting(
                node,
                "comparison",
                "Greater than"
            )

            operator = self.COMPARISONS.get(comparison)

            if operator is None:
                raise CodeGenerationError(
                    f"Unsupported comparison '{comparison}' "
                    f"in node '{node_name}'."
                )

            compare_value = self.to_python_expression(
                self.get_setting(node, "compare_value", "0")
            )

            return (
                [
                    f"if {variable} {operator} {compare_value}:"
                ],
                f"This node checks whether '{variable}' "
                f"satisfies the condition. Python uses an if "
                f"statement to execute code only when a condition "
                f"evaluates to True.",
                [
                    "if statement",
                    "Boolean expressions",
                    "Comparison operators",
                ]
            )

        elif node_type == "OUTPUT":

            message = self.get_setting(
                node,
                "message",
                "Hello!"
            )

            expression = self.to_python_expression(message)

            return (
                [f"print({expression})"],
                "This node displays information to the user. "
                "Python's print() function displays text and values "
                "in the console.",
                [
                    "print()",
                    "Output",
                    "Strings",
                ]
            )

        elif node_type == "END":

            return (
                ["# End of flowchart"],
                "The END node marks the completion of the flowchart. "
                "Python reaches the end of the generated program "
                "naturally.",
                [
                    "Program termination",
                ]
            )

        raise CodeGenerationError(
            f"Cannot generate code for node type: {node_type}"
        )

    # ======================================================
    # STRUCTURED CODE GENERATION
    # ======================================================

    def emit_path(self, current, stop_node=None, indent=0):

        while current is not None and current is not stop_node:

            node_key = id(current)

            if node_key in self.visited:
                raise CodeGenerationError(
                    f"Node '{self.get_node_name(current)}' "
                    "was encountered more than once. "
                    "The flowchart may contain an unsupported "
                    "branch structure."
                )

            self.visited.add(node_key)

            node_type = self.get_node_type(current)

            if node_type == "CONDITION":

                connections = self.get_connections(current)

                true_target = next(
                    target
                    for branch, target in connections
                    if branch == "true"
                )

                false_target = next(
                    target
                    for branch, target in connections
                    if branch == "false"
                )

                merge = self.find_branch_merge(
                    true_target,
                    false_target
                )

                code_lines, explanation, concepts = (
                    self.generate_node(current)
                )

                start_line = len(self.lines) + 1

                for line in code_lines:
                    self.lines.append(
                        "    " * indent + line
                    )

                # TRUE branch.
                self.emit_path(
                    true_target,
                    stop_node=merge,
                    indent=indent + 1
                )

                # ELSE statement.
                self.lines.append(
                    "    " * indent + "else:"
                )

                # FALSE branch.
                self.emit_path(
                    false_target,
                    stop_node=merge,
                    indent=indent + 1
                )

                end_line = len(self.lines)

                section = GeneratedSection(
                    node_index=self.node_indexes[node_key],
                    node_id=getattr(current, "node_id", None),
                    node_type=node_type,
                    node_name=self.get_node_name(current),
                    code="\n".join(
                        self.lines[start_line - 1:end_line]
                    ),
                    explanation=explanation,
                    concepts=concepts,
                    start_line=start_line,
                    end_line=end_line,
                    node_ref=current,
                )

                self.sections.append(section)

                current = merge

                continue

            code_lines, explanation, concepts = (
                self.generate_node(current)
            )

            indented_lines = [
                "    " * indent + line
                for line in code_lines
            ]

            self.add_section(
                current,
                indented_lines,
                explanation,
                concepts
            )

            connections = self.get_connections(current)

            if node_type == "END":
                current = None

            else:
                current = connections[0][1]

    # ======================================================
    # GENERATE COMPLETE PROGRAM
    # ======================================================

    def generate(self):

        start_node = self.validate_graph()

        self.sections = []
        self.visited = set()
        self.lines = []

        self.detect_numeric_variables()

        self.lines.extend([
            "# Generated by LogicFlow",
            "# Visual logic converted into Python",
            "",
        ])

        self.emit_path(start_node)

        if len(self.visited) != len(self.nodes):

            raise CodeGenerationError(
                "Some flowchart nodes were not converted into Python."
            )

        code = "\n".join(self.lines).rstrip() + "\n"

        return GeneratedProgram(
            code=code,
            sections=self.sections
        )
